class Solution {
    public long findTheArrayConcVal(int[] nums){
        long answer=0;
        for(int left=0,right=nums.length-1;left<=right;left++,right--)answer+=left==right?nums[left]:Long.parseLong(String.valueOf(nums[left])+nums[right]);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun findTheArrayConcVal(nums:IntArray):Long{
        var answer=0L;
        var left=0;
        var right=nums.lastIndex;
        while(left<=right){
            answer+=if(left==right)nums[left].toLong() else (nums[left].toString()+nums[right]).toLong();
            left++;
            right--
        };
        return answer
    }
}

